const items = $input.all();
const now = new Date();
const results = [];
for (const item of items) {
  const expiryStr = item.json.expiryDate || item.json.ExpiryDate || '';
  if (!expiryStr) continue;
  const expiry = new Date(expiryStr);
  const daysUntilExpiry = Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
  const isExpired = daysUntilExpiry < 0;
  const isExpiringSoon = daysUntilExpiry >= 0 && daysUntilExpiry <= 30;
  if (isExpired || isExpiringSoon) {
    results.push({
      json: {
        documentName: item.json.documentName || item.json.DocumentName || 'Unknown',
        documentType: item.json.documentType || item.json.DocumentType || 'General',
        expiryDate: expiryStr,
        daysUntilExpiry,
        status: isExpired ? 'EXPIRED' : daysUntilExpiry <= 7 ? 'CRITICAL' : 'WARNING',
        owner: item.json.owner || item.json.Owner || 'Unassigned',
        ownerEmail: item.json.ownerEmail || item.json.OwnerEmail || ''
      }
    });
  }
}
if (results.length === 0) {
  results.push({ json: { message: 'No documents expiring within 30 days' } });
}
return results;

